INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (74272,1,0,'A waste of air. Come, friend, we have much to discuss.',12,1,100.0,274,0,46697,79190,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (74272,2,0,'The ritual is ready, $n. Let me know when you wish to begin.',12,0,100.0,1,0,46698,79191,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (74272,3,0,'This Iron Tide comes for us because Durotan is strong and the Frostwolf would not join them.',12,0,100.0,1,0,46699,79255,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (74272,4,0,'The elements once spoke to me... now I hear only whispers. Is this our fate, or a warning?',12,0,100.0,25,0,46700,79192,0,'LegionCore');
